// sw.js — offline support. VERSION and ASSETS are generated by the factory from the real file list
// (web_build.finalize_sw) right before the tests run; the builder does not edit this file.
const VERSION = '0dffdefdce';
const ASSETS = ["./", "./app.js", "./compress.js", "./icon.svg", "./icons/icon-192.png", "./icons/icon-512.png", "./index.html", "./manifest.webmanifest", "./review/REVIEW.md", "./review/desktop-dark-advanced.png", "./review/desktop-dark-empty.png", "./review/desktop-dark-full.png", "./review/desktop-dark-result.png", "./review/desktop-dark-working.png", "./review/desktop-light-batch.png", "./review/desktop-light-emptycustom.png", "./review/desktop-light-errors.png", "./review/desktop-light-gif-inflated.png", "./review/desktop-light-result.png", "./review/desktop-light-unreached.png", "./review/desktop-light-webp-error.png", "./review/offline-result.png", "./review/phone-dark-advanced.png", "./review/phone-dark-empty.png", "./review/phone-dark-full.png", "./review/phone-dark-result.png", "./review/phone-dark-working.png", "./review/phone-light-advanced.png", "./review/phone-light-empty.png", "./review/phone-light-full.png", "./review/phone-light-result.png", "./review/phone-light-txt-error.png", "./review/phone-light-working.png", "./review/review.json", "./site.js", "./styles.css", "./worker.js"];
const CACHE = `tool-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never intercept third-party requests (page-view counter)
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res && res.ok && res.type === 'basic') {
        const copy = res.clone();
        caches.open(CACHE).then((c) => c.put(req, copy));
      }
      return res;
    }).catch(() => caches.match('./index.html')))
  );
});
